using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Xml.Linq;using V15Voice;
public static class AiTimelineTests {
 static int n;static string folder;static void Check(bool b,string name){if(!b)throw new Exception(name);Console.WriteLine("PASS "+name);n++;}static void Reject(Action a,string name){try{a();}catch{Check(true,name);return;}throw new Exception(name);}
 sealed class Engine:KokoroEngine {public static int Calls;public bool Fail;public override void CheckFiles(){if(Fail)throw new Exception("fixture missing model");}public override Wave Generate(string text,double speed,string output){Calls++;int count=System.Text.RegularExpressions.Regex.Matches(text,@"\b\w+\b").Count;int size=(int)(Math.Max(.3,count*.30)/speed*24000);return new Wave{Rate=24000,Samples=Enumerable.Range(0,size).Select(i=>i<size-1200?(short)(5000*Math.Sin(i*.063)):(short)0).ToArray()};}}
 sealed class Writer:ITextRewriter {public int Calls;public Func<int,string> Reply;public string Rewrite(string prompt,Func<bool> cancel,Action<string> activity){if(cancel())throw new OperationCanceledException();Calls++;return Reply(Calls);}}
 static string Reply(int id,string text){return LocalAi.Json(new AiRewriteText{cues=new List<AiCueText>{new AiCueText{id=id,text=text}}});}
 static VoiceSettings Settings(){return new VoiceSettings{Key="K:3",Mode=0,Breathing=2,Slow=false,Normalize=false,Speed=1,MinSpeed=.9,MaxSpeed=1.3,GentleFit=true};}
 static List<Cue> Script(){return Scripts.ParseSrt("1\n00:00:00,200 --> 00:00:03,500\nJohn was standing there for a very long time because the door had finally opened.\n\n2\n00:00:03,700 --> 00:00:07,000\nThis small detail changes the whole story for everyone.\n");}
 static AiRepairSession Open(string name,List<Cue> c=null,VoiceSettings s=null,bool shortText=false,string fingerprint="model1"){c=c??Script();string source=Path.Combine(folder,name+".srt");if(!File.Exists(source))File.WriteAllText(source,Scripts.ToSrt(c));return AiRepairSession.Open(source,c,folder,s??Settings(),shortText,fingerprint);}
 static KokoroEngine New(string role){return new Engine{Root=folder,VoiceName="Fixture "+role,DeviceMode="cpu",Archive=new SpeechArchive(Path.Combine(folder,"archive"))};}
 public static void Main(){folder=Path.Combine(Path.GetTempPath(),"V15 AI timeline "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);var c=Script();string hash=AiRepairSession.SnapshotHash(c);var p=Open("success");string sourceHash=StateFiles.Hash(p.Source);var writer=new Writer{Reply=i=>Reply(1,"John couldn't believe the door had finally opened.")};AiTimeline.Run(p,writer,New,()=>false,(i,m)=>{},false);Check(writer.Calls==1&&p.Rows[0].Best!=null&&!p.Rows[1].Original.NeedsRepair,"AI only rewrites failing unit after real measurement; passing unit kept");Check(p.Rows[0].Accepted==0&&p.Effective()[0].Text==c[0].Text,"Proposal mode never silently changes script");p.Rows[0].Accepted=p.Rows[0].Best.Number;var effective=p.Effective();Check(effective[0].Text.Contains("couldn't")&&effective[1].Text==c[1].Text&&effective[0].Start==c[0].Start&&effective[0].End==c[0].End,"Accept applies only validated words and keeps original timeline");Check(sourceHash==StateFiles.Hash(p.Source)&&hash==AiRepairSession.SnapshotHash(c),"Original file and input snapshot remain unchanged");p.Save();var resumed=Open("success");Check(resumed.Rows[0].Chosen!=null&&resumed.Rows[1].Original.Valid,"Saved repair session restores accepted proposal and successful measurements");int calls=writer.Calls,tts=Engine.Calls;AiTimeline.Run(resumed,writer,New,()=>false,(i,m)=>{},true);Check(writer.Calls==calls&&Engine.Calls==tts,"Retry skips already measured/passing entries and reuses accepted result");resumed.Rows[0].Accepted=0;Check(resumed.Effective()[0].Text==c[0].Text,"Undo restores original words");
  var different=Open("success",null,null,false,"model2");Check(different.Folder!=p.Folder&&different.Rows[0].Original==null,"Voice/model fingerprint invalidates previous repair measurements");var changed=Settings();changed.Speed=.95;changed.MinSpeed=.9;var newSettings=Open("success",null,changed);Check(newSettings.Folder!=p.Folder,"Speed/punctuation/settings changes get distinct sessions");
  var s=Settings();var restored=VoiceSettings.From(new VoiceSettings{AiMode=2,AiFixShort=false}.Xml());Check(restored.AiMode==2&&!restored.AiFixShort&&VoiceSettings.From(new XElement("settings")).AiMode==0,"AI mode persists and old sessions default to off");
  foreach(string invalid in new[]{"no json","{broken}",Reply(9,"Wrong ID."),"{\"cues\":[]}",Reply(1,"[B] Sneaky change."),Reply(1,"00:00:00,000 --> 00:00:01,000"),Reply(1,"")})Reject(()=>AiTimeline.Candidate(invalid,new List<Cue>{c[0]}),"Reject malformed proposal "+invalid.Substring(0,Math.Min(30,invalid.Length)));
  var numbered=Scripts.ParseSrt("1\n00:00:00,000 --> 00:00:03,000\nThe door opened after 12 days.\n");Reject(()=>AiTimeline.Candidate(Reply(1,"The door opened after 13 days."),numbered),"Reject changed numeric facts");var named=Scripts.ParseSrt("1\n00:00:00,000 --> 00:00:03,000\nHe finally found John near the door.\n");Reject(()=>AiTimeline.Candidate(Reply(1,"He found Peter near the door."),named),"Reject dropped detected proper name");var candidate=VoiceRenderReport.Snapshot(c);candidate[0].Start+=.1;Reject(()=>AiTimeline.ValidateCandidate(c,candidate),"Reject changed geometry");candidate=VoiceRenderReport.Snapshot(c);candidate[0].Speaker="B";Reject(()=>AiTimeline.ValidateCandidate(c,candidate),"Reject changed speaker role");Check(LocalAi.Parse<AiRewriteText>("```json\n"+Reply(1,"Braces {inside} text.")+"\n```\n> EOF").cues[0].text=="Braces {inside} text.","JSON extraction handles escaped strings, braces and completion trailer");
  var bad=Open("bad-response");var badWriter=new Writer{Reply=i=>"not JSON"};AiTimeline.Run(bad,badWriter,New,()=>false,(i,m)=>{},true);Check(badWriter.Calls==2&&bad.Rows[0].Accepted==0&&bad.Rows[0].Attempts.All(a=>a.Error.Length>0),"Invalid AI output is bounded to two attempts and never accepted");var badResume=Open("bad-response");Check(badResume.Rows[0].Attempts.Count==2,"Malformed-attempt history persists across restart without resetting retry cap");
  var modelError=Open("tts-error");var never=new Writer{Reply=i=>Reply(1,"Should not run.")};AiTimeline.Run(modelError,never,role=>new Engine{Root=folder,Fail=true},()=>false,(i,m)=>{},true);Check(never.Calls==0&&modelError.Rows.All(r=>r.Original.Error.Contains("missing model")),"TTS/model error never triggers language rewriting");Check(File.ReadAllText(modelError.Report).Contains("chưa đo hoàn tất")&&File.ReadAllText(modelError.Report).Contains("fixture missing model"),"Model failure report has diagnostic cause without fabricated duration");
  var cancelled=Open("cancel");bool stop=true;Reject(()=>AiTimeline.Run(cancelled,writer,New,()=>stop,(i,m)=>{},true),"Cancel stops before synthesis or AI call");Check(cancelled.Outcome.Contains("Đã dừng")&&File.Exists(cancelled.Report),"Cancellation always persists report");File.AppendAllText(p.Source,"\nchanged");Reject(()=>p.Validate(),"Changed source blocks apply/export rather than overwriting new content");
  var text=LongText.Parse("This has no fixed speech window.");Reject(()=>Open("prose",text),"Natural TXT is not treated as fixed SRT timeline");s=Settings();s.Mode=1;Reject(()=>Open("flexible",null,s),"Flexible mode does not fabricate a fixed target");
  var two=Scripts.ParseSrt("1\n00:00:00,000 --> 00:00:03,300\n[A] John was standing there for a very long time because the door had finally opened.\n\n2\n00:00:03,300 --> 00:00:06,600\n[B] This small detail changes the whole story for everyone.\n");s=Settings();s.TwoVoices=true;s.VoiceBKey="private:B";var dual=Open("dual",two,s);writer=new Writer{Reply=i=>Reply(1,"John couldn't believe the door had finally opened.")};AiTimeline.Run(dual,writer,New,()=>false,(i,m)=>{},true);Check(dual.Effective()[0].Speaker=="A"&&dual.Effective()[1].Speaker=="B"&&dual.Rows[1].Original.Voice=="Fixture B","Two-voice correction routes actual measurement and preserves A/B assignments");
  s=Settings();s.Mode=2;s.TwoVoices=true;s.VoiceBKey="private:B";var anchored=Open("anchored",two,s);Check(anchored.Rows.Count==2&&anchored.Rows.All(r=>r.Stage.Cues.Select(SpeakerScript.Role).Distinct().Count()==1),"V15.6 correction units respect real stage and speaker boundaries");
  var shortCues=Scripts.ParseSrt("1\n00:00:00,000 --> 00:00:03,300\nThe door opened.\n");var shorter=Open("short",shortCues,null,true);AiTimeline.Run(shorter,writer,New,()=>false,(i,m)=>{},false,false);Check(shorter.Rows[0].Original.Fits&&shorter.Rows[0].Original.NeedsRepair&&shorter.Rows[0].Original.Tail>1,"Short cue is detected from measured spare time instead of padding to claim success");
  string report=File.ReadAllText(dual.Report);Check(report.Contains("Gốc #1")&&report.Contains("Sửa #1")&&report.Contains("ĐÃ CHẤP NHẬN")&&report.Contains("tốc độ")&&report.Contains("Fixture B"),"AI report contains before/after, acceptance, voice identity and speed");var options=new RenderOptions{AiRepair=dual,TwoVoices=true,Locked=true,SlowShort=false,Breathing=BreathMode.None,ReportContext=new VoiceReportContext{SourcePath=dual.Source,SourceCues=dual.Effective()}};using(var router=new TwoVoiceEngine(New("A"),New("B"),"K:3","private:B",dual.Effective())){string wav=Renderer.Render(dual.Effective(),router,options,Path.Combine(folder,"final.wav"),(i,m)=>{});Check(File.Exists(wav)&&FinalAudio.PcmFrames(wav)==158400&&options.RunReport.Build().Contains("LỊCH SỬ SỬA LỜI AI"),"Final ordinary renderer verifies full WAV and embeds complete repair history");}
  Console.WriteLine("TOTAL AI TIMELINE "+n+" passed. Fixtures: "+folder);
 }
}
